('emerald-ex-1.0.4', 'abilities', 'pokemon_emerald_ex_1.0.4_abilities.json', 'dafec7043f8c0a2e042e40e64af3201981b6c5cb1969a99c2ef50f8fb3d2a60e', '{"game":"Pokémon Emerald EX","version":"1.0.4","sourceRom":"Pokemon Emerald Ex (1.0.4) hkcmoris.gba","sourceRomSha256":"6150445dadedc9e95cb16ffb0be1bce37e632ce2fd2777bec6201eeec8e54e57","abilityCount":311,"speciesFormCount":1523,"distinctAbilitiesUsedBySpecies":310,"notes":["Ability definitions and species ability slots were extracted directly from the supplied ROM.","Ability ID 0 is the engine''s NONE ability and is represented as null in species slots.","Each species/form has two normal ability slots and one hidden-ability slot.","Duplicate ability IDs across slots are preserved; battle-only forms such as Mega Pokémon can intentionally use the same ability in all slots.","aiRating and ability flags are engine metadata used by the ROM''s battle/ability logic."]}');
